gh issue view 190 --json body -q .body | head -80 && echo '====' && gh issue list --limit 40 --state open --label agent-ready --json number,title,labels | python3 -c "
import sys,json
issues=json.load(sys.stdin)
def pri(labels):
  names={l['name'] for l in labels}
  for p in ['P0-critical','P1-high','P2-medium','P3-low']:
    if p in names: return p
  return 'P?'
for i in sorted(issues, key=lambda x:(pri(x['labels']), x['number'])):
  labs=','.join(l['name'] for l in i['labels'] if l['name'].startswith('P') or l['name'] in ('epic','testing','hig','security','modernization','documentation','feature','tech-debt'))
  print(f\"#{i['number']}: {i['title']}  [{pri(i['labels'])}] {labs}\")
"
